declarations.declaration:
export type OpenClawActionTaskType =
  | 'OPENCLAW_APPLICABILITY_EVALUATION'
  | 'OPENCLAW_DYNAMIC_EVALUATION'
  | 'OPENCLAW_INTERACTIVE_REVIEW'
  | 'OPENCLAW_OVERALL_SYNTHESIS'
  | 'OPENCLAW_TRANSLATE';

export interface ActionEnvelopeArtifactRef {
  ref: string;
  sha256: string;
}

export interface ActionEnvelopeMissingInput {
  code: string;
  message: string;
}

/**
 * Exact Host-owned RuleSet snapshot used to build one dynamic task. The
 * binding lives inside modelInput, so the existing TaskEnvelope inputHash and
 * durable ActionAttempt row seal it without introducing another envelope or
 * current-pointer mechanism.
 */
export interface OpenClawDynamicRuleSetBinding {
  schemaVersion: 'wiselink.3_1.dynamic_rule_set_binding.v1';
  snapshotId: string;
  criterionSetId: string;
  criterionSetHash: string;
  memberIdentityHash: string;
  criteriaCount: number;
  rulePackVersion: string;
  artifactRef: string;
  artifactDigest: string;
  artifactVersion: string;
  activationRevision: number;
}

/**
 * Immutable Host-created input delivered to OpenClaw after a successful
 * ActionAttempt lease claim.
 */
export interface OpenClawTaskEnvelope {
  schemaVersion: 'wiselink.3_1.openclaw_task_envelope.v1';
  actionAttemptId: string;
  operationRef: string;
  taskType: OpenClawActionTaskType;
  priority: number;
  tenantId: string;
  workItemId: string;
  inputRevision: number;
  baseRevision: number;
  documentVersionId: string;
  sourceRefs: ActionEnvelopeArtifactRef[];
  allowedConnectors: string[];
  hostResolvedMissingInputs: ActionEnvelopeMissingInput[];
  modelInput: Record<string, unknown>;
  /** Host routing only; never forwarded as part of modelInput. Absent on historical tasks. */
  executionModel?: CanonicalExecutionModelSelection;
  deadline: string;
  idempotencyKey: string;
  inputHash: string;
}

export interface OpenClawDynamicTaskModelInput extends Record<string, unknown> {
  ruleSetBinding: OpenClawDynamicRuleSetBinding;
}

export interface OpenClawDynamicTaskEnvelope extends OpenClawTaskEnvelope {
  taskType: 'OPENCLAW_DYNAMIC_EVALUATION';
  modelInput: OpenClawDynamicTaskModelInput;
}

/** New Matter requests never include a member WorkItem execution identity. */
export interface EngineeringMatterAttemptSubject {
  kind: 'ENGINEERING_MATTER';
  matterId: string;
  matterRevisionId: string;
}

export type EngineeringMatterAttemptTrigger =
  | { kind: 'SOURCE_CHANGE'; inputIds: string[] }
  | { kind: 'COMPOSITION_CHANGE'; previousMatterRevisionId: string | null }
  | { kind: 'REVISIT'; workRef: string; conditionIds: string[] }
  | { kind: 'USER_REQUEST'; requestId: string; instruction: string };

export interface OpenClawMatterTaskEnvelope extends Omit<
  OpenClawTaskEnvelope,
  'schemaVersion' | 'taskType' | 'workItemId' | 'documentVersionId'
> {
  schemaVersion: 'wiselink.3_1.openclaw_task_envelope.v2';
  taskType: 'OPENCLAW_MATTER_ASSESSMENT';
  subject: EngineeringMatterAttemptSubject;
  trigger: EngineeringMatterAttemptTrigger;
  /** Host-captured execution basis; never supplied by the model. */
  workingBasis: {
    inputs: EngineeringMatterWorkingInputBinding[];
    priorWorkRef: string | null;
  };
}

export type AnyOpenClawTaskEnvelope =
  | OpenClawTaskEnvelope
  | OpenClawMatterTaskEnvelope;

export type OpenClawResultBusinessOutcome =
  | 'CANDIDATE_READY'
  | 'UNKNOWN'
  | 'WAITING_INPUT'
  | 'NOT_PRODUCED';

/**
 * Complete executor result. The model output is data inside the envelope; it
 * is never accepted as a free-standing string or silently replaced with {}.
 */
export interface OpenClawModelResultEnvelope {
  executionKind?: never;
  modelRequests?: never;
  sourceWork?: never;
  schemaVersion: 'wiselink.3_1.openclaw_result_envelope.v1';
  actionAttemptId: string;
  operationRef: string;
  taskType: OpenClawActionTaskType;
  workItemId: string;
  baseRevision: number;
  status: 'SUCCEEDED' | 'WAITING_INPUT' | 'FAILED';
  businessOutcome: OpenClawResultBusinessOutcome;
  candidateStatus: 'UNKNOWN' | 'WAITING_INPUT' | null;
  modelOutput: string | null;
  outputArtifactRefs: ActionEnvelopeArtifactRef[];
  sourceRefs: ActionEnvelopeArtifactRef[];
  factsConsidered: string[];
  missingInputs: ActionEnvelopeMissingInput[];
  conflicts: string[];
  warnings: string[];
  modelVersion: string;
  promptVersion: string;
  skillVersion: string;
  toolVersions: Record<string, string>;
  runMetrics: {
    durationMs: number;
    inputUnits: number;
    outputUnits: number;
  };
  contentHash: string;
  errorCode: string | null;
  errorDetail: string | null;
}

/** A Host-authorized finish of an existing COMPLETE JAWR, without a model request. */
export interface OpenClawSavedWorkReconciliationResultEnvelope extends Omit<
  OpenClawModelResultEnvelope, 'modelVersion' | 'executionKind' | 'modelRequests' | 'sourceWork'
> {
  executionKind: 'HOST_SAVED_WORK_RECONCILIATION';
  status: 'SUCCEEDED';
  businessOutcome: 'CANDIDATE_READY';
  candidateStatus: null;
  modelRequests: 0;
  modelVersion: null;
  sourceWork: { workRevisionRef: string; sourceActionAttemptId: string };
}

export interface OpenClawMatterResultEnvelope extends Omit<
  OpenClawResultEnvelope,
  'schemaVersion' | 'taskType' | 'workItemId' | 'modelVersion' | 'skillVersion' | 'runMetrics' | 'executionKind' | 'modelRequests' | 'sourceWork'
> {
  schemaVersion: 'wiselink.3_1.openclaw_result_envelope.v2';
  taskType: 'OPENCLAW_MATTER_ASSESSMENT';
  subject: EngineeringMatterAttemptSubject;
  modelVersion: string | null;
  skillVersion: string | null;
  runMetrics: { durationMs: number; inputUnits: number | null; outputUnits: number | null };
  producer?: { kind: 'OFFICIAL_PLUGIN'; instanceId: string; pluginVersion: string;
    actionKey: 'textToJson'; concreteModel: null };
}

export type AnyOpenClawResultEnvelope =
  | OpenClawResultEnvelope
  | OpenClawMatterResultEnvelope;

interface OpenClawClaimBase {
  attemptRef: string;
  leaseToken: string;
  leaseGeneration: number;
  leaseExpiresAt: string;
  task: OpenClawTaskEnvelope;
}

export interface OpenClawRunningLeaseClaim extends OpenClawClaimBase {
  status: 'RUNNING';
}

export interface OpenClawCommittingRecoveryClaim extends OpenClawClaimBase {
  status: 'COMMITTING';
  recoveryResult: OpenClawResultEnvelope;
}

export type OpenClawLeaseClaim =
  | OpenClawRunningLeaseClaim
  | OpenClawCommittingRecoveryClaim;

export interface BeginDynamicEvaluationResult {
  attemptRef: string;
  status: 'RUNNING' | 'COMMITTING';
  leaseToken: string;
  leaseGeneration: number;
  leaseExpiresAt: string;
  task: OpenClawDynamicTaskEnvelope;
  recoveryResult?: OpenClawResultEnvelope;
  modelInput: Record<string, unknown>;
}

export interface CommitDynamicEvaluationResult {
  workItemId: string;
  workItemRevision: number;
  status: CanonicalIntegratedAssessmentProjection['status'];
  baseRules: CanonicalBaseRuleCandidateProjection;
}

export interface BeginJobAidProblemResult {
  attemptRef: string;
  status: 'RUNNING' | 'COMMITTING';
  leaseToken: string;
  leaseGeneration: number;
  leaseExpiresAt: string;
  task: OpenClawTaskEnvelope;
  recoveryResult?: OpenClawResultEnvelope;
  modelInput: JobAidProblemModelInput;
  selectedDiscoveryRefs: string[];
}

export interface JobAidSourceBinding {
  kind?: 'SOURCE_FILE';
  workItemId: string;
  documentVersionId: string;
  artifactSha256: string;
  artifactRef: string;
}

export interface JobAidProblemModelInput extends Record<string, unknown> {
  executionMode?: 'PROGRAM_CONTROLLED_V1';
  programOriginal?: {
    binding: import('@shared/document-original.interface').DocumentOriginalBinding;
    coverage: import('@shared/document-original.interface').DocumentOriginalCoverage;
    units: import('@shared/canonical-translation-v2.interface').TranslationStructuredSource['units'];
    sourceLocators: import('@shared/canonical-translation-v2.interface').TranslationStructuredSource['sourceLocators'];
    findings: import('@shared/canonical-translation-v2.interface').TranslationStructuredSource['findings'];
  };
  contentValidationVersion?: 'jobaid-semantic.v1';
  /** Metadata only. A directory and approval provenance are not a body READ. */
  tdmsContext?: Pick<TdmsRuntimeTaskContext, 'schemaVersion' | 'projection'>;
  tdmsReviewContext?: TdmsReviewContext;
  schemaVersion: typeof JOBAID_PROBLEM_TASK_SCHEMA | typeof JOBAID_PROBLEM_SOURCE_STATEMENT_TASK_SCHEMA;
  /** Absent on sealed historical tasks: retain their original exact projection. */
  evidenceProjectionVersion?: OverallEvidenceProjectionVersion;
  purpose:
    | 'INITIAL_PROBLEM_ASSESSMENT'
    | 'OVERALL_CONSISTENCY'
    | 'PROBLEM_REVIEW';
  preparation?: JobAidPreparationView;
  methodBinding: typeof JOBAID_METHOD_BINDING;
  documentOverview: CanonicalCommonAssessmentContext['primaryDocument'] & {
    sections: Array<{ title: string; sourceRefs: string[] }>;
    original?: { binding: import('@shared/document-original.interface').DocumentOriginalBinding;
      semanticMap?: import('@shared/document-semantic-map.interface').DocumentSemanticMap | null;
      coverage: import('@shared/document-original.interface').DocumentOriginalCoverage;
      findings: import('@shared/canonical-translation-v2.interface').TranslationStructuredSource['findings'] };
  };
  hostApplicability: Pick<
    NonNullable<CanonicalWorkItemProjection['applicability']>,
    | 'decision'
    | 'currentness'
    | 'aircraftNumber'
    | 'assessmentAsOf'
    | 'blockingUnknownCount'
    | 'sourceExpressionCount'
    | 'pass'
  > | null;
  availableSources: Array<{
    ref: string;
    kind: AssessmentEvidence['kind'];
    title: string;
    versionLabel: string | null;
    locator: string | null;
    documentVersionId?: string;
    sourceRefId?: string;
    parseRunId?: string;
    carrierRangeRef?: string;
    sourceStatement?: Pick<DocumentActivityAssessmentProjection['entries'][number], 'reference'|'label'|'semanticFieldsAvailability'|'scopeBasis'|'sourceSchemaVersion'>;
  }>;
  /** New mixed Review alone inlines exact records once; initial/Overall read on demand. */
  sourceStatements?: DocumentActivityAssessmentProjection['records'];
  activityContexts?: DocumentActivityAssessmentProjection['activityContexts'];
  sourceStatementAvailability?: {status:'AVAILABLE'|'NOT_SAVED'|'NOT_INDEXED'; semanticFieldsAvailability:'LEGACY_PARTIAL'|'CAPTURED_FIELDS_ONLY'; limitations:string[]};
  deliveredEvidence: ReturnType<typeof overallModelEvidenceRegistry>;
  previousWork: {
    workRevisionRef: string;
    workRevision: number;
    overviewStatus?: JobAidProblemWorkContent['overviewStatus'];
    content: JobAidProblemModelWorkContent;
  } | null;
  expectedWorkRevision: number;
  capabilities: JobAidProblemWorkContent['capabilities'];
  historyReview: JobAidProblemWorkContent['historyReview'];
  /** Actual earlier user wording remains discussion, never controlled facts. */
  discussion: CanonicalCommonAssessmentContext['discussion'];
  /** Absent only on tasks persisted before source provenance was projected. */
  contextPackage?: JobAidAssessmentContextPackage;
  knowledgeAccess?: import("@shared/jobaid-problem-assessment.interface").JobAidKnowledgeAccess;
}

export type JobAidProblemModelWorkContent = Pick<JobAidProblemWorkContent,
  'schemaVersion' | 'headline' | 'listBrief' | 'roundCompletion' | 'completionReason' | 'changeSummary' | 'unchangedExplanation'> & {
  overview: string;
  issues: Array<Omit<JobAidProblemIssue, 'issueRef' | 'sourceDependencies' | 'premiseRefs' | 'legacyCriterionRefs' | 'riskScenarios'> & { riskScenarios: Array<Omit<JobAidProblemIssue['riskScenarios'][number], 'gradeMeaning'>> }>;
};

export interface JobAidProblemTaskInput extends Record<string, unknown> {
  executionMode?: 'PROGRAM_CONTROLLED_V1';
  requestedModelRef?: string;
  contentValidationVersion?: 'jobaid-semantic.v1';
  /** Exact existing Review input selection, retained only in the trusted wrapper. */
  preparationScope?: JobAidPreparationScope;
  /** Sealed by Host for new automatic work only; absent on manual/historical tasks. */
  automaticWorkItemLease?: AutomaticWorkItemTaskLease;
  /** Exact saved candidate recovery; never a new model analysis. */
  savedWorkReconciliation?: {
    executionKind: 'HOST_SAVED_WORK_RECONCILIATION';
    modelRequests: 0;
    workRevisionRef: string;
    workRevision: number;
    sourceActionAttemptId: string;
  };
  /** Optional only on newly sealed tasks; never backfilled into old checkpoints. */
  tdmsContext?: TdmsRuntimeTaskContext;
  tdmsReviewContext?: TdmsReviewContext;
  schemaVersion: typeof JOBAID_PROBLEM_TASK_SCHEMA | typeof JOBAID_PROBLEM_SOURCE_STATEMENT_TASK_SCHEMA;
  knowledgeBinding?: import("./initial-assessment-knowledge.service").InitialKnowledgeBinding;
  actorUserId: string;
  permissionSnapshotVersion: string;
  sourceBindings: JobAidSourceBinding[];
  sourceCatalog: AssessmentEvidence[];
  /** Host-only exact snapshots, never an extra model directory or input body. */
  sourceActivityProjections?: DocumentActivityAssessmentProjection[];
  initiallyDeliveredRefs: string[];
  previousWork: JobAidWorkRevision | null;
  modelInput: JobAidProblemModelInput;
}

/** Routing metadata, never provider credentials or a browser-supplied endpoint. */
export interface CanonicalExecutionModelSelection {
  modelRef: string;
  displayName: string;
  providerKind: 'BUILT_IN' | 'CUSTOM';
  settingsRevision: number;
  selectedAt: string;
}

export type AutomaticWorkItemClaimResult =
  | { status: 'IDLE'; reviewAfterWorkItemId?: string; documentAfterRef?: string }
  | { status: 'DOCUMENT_PENDING'; documentVersionId: string; deliveryRef: string;
      documentAfterRef?: string }
  | {
      status: 'REVIEW_PENDING';
      workItemId: string;
      reviewTurnRef: string;
      reviewAfterWorkItemId: string;
    }
  | {
      status: 'OVERALL_PENDING';
      workItemId: string;
      reviewTurnRef: string;
      workRevisionRef: string;
      reviewAfterWorkItemId: string;
    }
  | {
      status: 'CLAIMED';
      workItemId: string;
      requestId: string;
      documentVersionId: string;
      workItemRevision: number;
      leaseToken: string;
      leaseGeneration: number;
      leaseExpiresAt: string;
    };

export interface NextAutomaticWorkItemRequest {
  resumeWorkItemId?: string;
  reviewAfterWorkItemId?: string;
  documentAfterRef?: string;
}

export interface AcknowledgeAutomaticWorkItemRequest {
  workItemId: string;
  leaseToken: string;
  leaseGeneration: number;
}

export interface AcknowledgeAutomaticWorkItemResponse {
  status: 'ACKNOWLEDGED';
  workItemId: string;
  replayed: boolean;
  acknowledgedAt: string;
}

export interface BlockAutomaticWorkItemRequest {
  workItemId: string;
  leaseToken: string;
  leaseGeneration: number;
  /** Explicit operator parking; normal terminal-failure BLOCK is unchanged. */
  expectedCancellation?: AutomaticWorkItemCancellationBinding;
  /** Cancellation receipt replay only: never creates a new BLOCK. */
  replayOnly?: true;
}

/** Expected control binding, never an assertion about provider termination. */
export interface AutomaticWorkItemCancellationBinding {
  requestId: string;
  workItemRevision: number;
  documentId: string;
  documentVersionId: string;
  sourceArtifactId: string;
  sourceFileSha256: string;
  sourceByteLength: number;
  attemptId: string;
  attemptRef: string;
  attemptNo: number;
  attemptRequestId: string;
  actionType: 'OPENCLAW_DYNAMIC_EVALUATION';
  inputRevision: number;
  baseRevision: number;
  inputHash: string;
  executionModel: CanonicalExecutionModelSelection;
}

export interface BlockAutomaticWorkItemResponse {
  status: 'BLOCKED';
  workItemId: string;
  blockedCode: string;
  replayed: boolean;
  blockedAt: string;
}

/** Model-facing context saved in the existing versioned assessment task input. */
export interface JobAidAssessmentContextPackage {
  basedOnWorkItemRevision: number;
  basedOnWorkingRevision: number | null;
  primaryDocument: CanonicalCommonAssessmentContext['primaryDocument'] & {
    readingStatus: CanonicalCommonAssessmentContext['documentReading']['status'];
  };
  supplementaryMaterials: {
    status: CanonicalCommonAssessmentContext['relatedMaterials']['status'];
    reason: string | null;
    items: Array<
      Omit<
        CanonicalCommonAssessmentContext['relatedMaterials']['items'][number],
        'availableSourceRefIds' | 'readFragments'
      > & {
        availableEvidenceRefs: string[];
        deliveredEvidenceRefs: string[];
      }
    >;
  };
  sourceOrigins: Array<{
    evidenceRef: string;
    origin: string;
    contentNature:
      | 'SOURCE_DOCUMENT_CONTENT'
      | 'SOURCE_DECLARED_PROFESSIONAL_OPINION'
      | 'UNVERIFIED_ENGINEER_STATEMENT'
      | 'UNVERIFIED_QUERY_RESPONSE'
      | 'PRIOR_CANDIDATE'
      | 'CONTROLLED_HOST_FACT'
      | 'METHOD_MATERIAL';
  }>;
  knowledgeRetrieval: {
    status: 'NOT_CONNECTED' | 'NOT_REQUESTED' | 'UNAVAILABLE';
    reason?: string;
    fragments: [];
  };
}

export interface JobAidKnowledgeAccess {
  available: boolean;
  reason?: string;
}

export interface JobAidKnowledgeQueryReceipt {
  queryRef: string | null;
  status: 'RUNNING' | 'COMPLETED' | 'FAILED' | 'UNKNOWN' | 'UNAVAILABLE';
  error: string | null;
  evidence: AssessmentEvidence[];
  candidateOnly: true;
  originalDocumentsVerified: false;
}

export interface JobAidMethodBinding {
  packRef: string;
  version: string;
  sources: Array<{
    sourceIdentity: string;
    versionLabel: string;
    documentVersionId: string | null;
    status: 'CONFIRMED' | 'VERSION_UNCONFIRMED';
  }>;
  attachment5: 'R00_CONTENT_REPORTED_R01_LINK_UNCONFIRMED';
}

export interface JobAidClassificationProposal {
  /** Exact delivered method definition; optional only for historical work. */
  definitionMatch?: { methodRef: string; definitionQuote: string };
  label: string;
  reason: string;
  basisRefs: string[];
}

export interface JobAidRiskScenario {
  scenario: string;
  conditions: string[];
  method: 'JA_AC_R01';
  severity: JobAidClassificationProposal | null;
  likelihood: JobAidClassificationProposal | null;
  /** Host calculation. Unknown never has score zero or an inferred low grade. */
  score: number | null;
  riskGrade: 1 | 2 | 3 | 4 | 5 | null;
  gradeMeaning: string | null;
  importantEvent: { event: string; basisRefs: string[]; reason: string } | null;
  limitations: string[];
  controlComparison: string;
}

export interface JobAidRequirementHandling {
  methodRef: string;
  requirement: string;
  conditions: string[];
  treatment:
    | 'ADDRESSED'
    | 'CONDITIONS_UNCONFIRMED'
    | 'NOT_APPLICABLE_WITH_BASIS'
    | 'LATER_BUSINESS_STAGE'
    | 'NOT_YET_ADDRESSED'
    | 'CONFLICT';
  /** A traceable passage in the issue body; whitespace is normalized when matching. */
  bodyQuote?: string;
  basisRefs: string[];
  explanation: string;
}

export interface JobAidProblemIssue {
  issueKey: string;
  issueRef: string;
  question: string;
  /** Complete candidate explanation with exact [[evidenceRef]] citations. */
  body: string;
  riskScenarios: JobAidRiskScenario[];
  measures: Array<{
    text: string;
    addresses: string;
    limitations: string[];
    status: 'PROPOSED' | 'REPORTED_IMPLEMENTED' | 'VERIFIED_EFFECTIVE';
    basisRefs: string[];
  }>;
  /** Separate method identities; no conversion to JA-AC grades. */
  otherClassifications: Array<{
    method:
      | 'SAE_EVENT_CATEGORY'
      | 'SOURCE_DOCUMENT_CLASSIFICATION'
      | 'EO_ATTRIBUTE';
    value: string;
    reason: string;
    basisRefs: string[];
  }>;
  openQuestions: Array<{
    question: string;
    affects: string;
    nextEvidence: string;
    reason: string;
  }>;
  requirementHandling: JobAidRequirementHandling[];
  sourceDependencies: string[];
  premiseRefs: string[];
  legacyCriterionRefs?: string[];
}

export interface JobAidProblemWorkContent {
  /** Historical read projection only; never a model-writable field. */
  historicalSourceSchema?: 'wiselink.jobaid-problem-work.v2';
  schemaVersion: typeof JOBAID_PROBLEM_WORK_SCHEMA;
  headline: string;
  listBrief: string;
  understanding: string;
  decisiveIssueKeys: string[];
  overviewStatus: 'NOT_AVAILABLE' | 'CURRENT' | 'STALE';
  issues: JobAidProblemIssue[];
  roundCompletion: 'IN_PROGRESS' | 'COMPLETE' | 'COMPLETE_WITH_OPEN_QUESTIONS';
  completionReason: string;
  changeSummary: string;
  unchangedExplanation: string;
  methodBinding: JobAidMethodBinding;
  /** All actual inputs, including important premises not eventually cited. */
  evidence: AssessmentEvidence[];
  readSourceRefs: string[];
  capabilities: Array<{
    capability: string;
    status:
      | 'AVAILABLE'
      | 'NOT_CONNECTED'
      | 'ACCESS_DENIED'
      | 'NOT_FOUND'
      | 'PARTIAL'
      | 'READ_FAILED';
    impact: string;
  }>;
  historyReview: {
    required: boolean;
    priorAssessmentRefs: string[];
    engineeringDocumentRefs: string[];
    coverage: 'AVAILABLE_HISTORY_REVIEWED' | 'PARTIAL' | 'NOT_REQUIRED';
    limitation: string | null;
  };
}

export interface JobAidWorkRevision {
  workRevisionRef: string;
  workItemId: string;
  workRevision: number;
  previousWorkRevisionRef: string | null;
  requestId: string;
  actionAttemptId: string;
  basedOnWorkItemRevision: number;
  documentVersionId: string;
  createdAt: string;
  content: JobAidProblemWorkContent;
}

export interface CanonicalJobAidProblemCandidateProjection {
  schemaVersion: typeof JOBAID_PROBLEM_RESULT_SCHEMA;
  status: 'CANDIDATE_ONLY';
  revision: number;
  sourceResultId: string;
  workRevisionRef: string;
  workRevision: number;
  issueCount: number;
  openQuestionCount: number;
  roundCompletion: 'COMPLETE' | 'COMPLETE_WITH_OPEN_QUESTIONS';
  methodBinding: JobAidMethodBinding;
  headline: string;
  listBrief: string;
  artifact: UnifiedPackageArtifactDescriptor;
  actionAttemptId: string;
  /** Saved once, shared by the default brief and detailed issue view. */
  readingResult: AssessmentReadingResult;
}

/** Exact Native-prepared payload; preparation alone is not evidence of a provider send. */
export interface JobAidProgramMaterialsRead {
  schemaVersion: 'wiselink.program-assessment-materials-read.v1';
  workItemId: string;
  attemptId: string;
  attemptRef: string;
  executionMode: 'PROGRAM_CONTROLLED_V1';
  executionModel: import('./api.interface').CanonicalExecutionModelSelection;
  preparedAt: string;
  submissionEvidence: 'PREPARED_NOT_CONFIRMED_SENT' | 'RESPONSE_RECEIVED';
  snapshot: { materials: Record<string, unknown>; modelRequest: Record<string, unknown> };
}

export interface JobAidWorkingReadModel {
  schemaVersion: 'wiselink.jobaid-working-read.v2';
  enabled: boolean;
  workItemId: string;
  /** Validated outer automatic-processing ACK, independent of later JobAid attempts. */
  autoProcessingAcknowledgement?: {
    workItemId: string;
    requestId: string;
    documentVersionId: string;
    acknowledgedAt: string;
  } | null;
  current: JobAidWorkRevision | null;
  /** Latest exact WorkItem evaluation request, independent of saved work. */
  latestAttempt: {
    attemptId: string;
    status: string;
    inputRevision: number | null;
    /** Exact dynamic-attempt record times, not Overall or queue ACK times. */
    createdAt?: string;
    startedAt?: string | null;
    completedAt?: string | null;
    /** Earliest saved revision belonging to this exact attempt; not first read. */
    firstSavedAt?: string | null;
  } | null;
  /** One selected execution from this read; not the complete attempt history. */
  selectedExecution?: {
    actionType: 'OPENCLAW_DYNAMIC_EVALUATION' | 'OPENCLAW_OVERALL_SYNTHESIS';
    executionMode?: import('./api.interface').CanonicalAssessmentExecutionMode | null;
    executionModel?: import('./api.interface').CanonicalExecutionModelSelection | null;
    /** Consumer observation, not an authoritative provider or attempt terminal state. */
    programProgress?: { phase: 'MATERIALS_READY' | 'MODEL_RESPONSE_SAVED'; checkpointRef: string; observedAt: string } | null;
    /** Metadata only; content requires the exact attempt's authorized lazy read. */
    programMaterialsAvailable?: boolean;
    attemptId: string;
    /** Exact persisted operation reference, independent of request identity. */
    attemptRef: string | null;
    status: string;
    createdAt: string;
    startedAt: string | null;
    completedAt: string | null;
  } | null;
  executionStatus: string | null;
  /** Optional for compatibility with Host versions before activity projection. */
  activity?: JobAidActivityRead | null;
  currentInputChanged: boolean;
  overallStatus: 'NOT_AVAILABLE' | 'CURRENT' | 'STALE';
  overallBasedOnWorkRevisionRef: string | null;
}

/** Exact Host identities; extraction and translation cannot manufacture these. */
export interface DocumentOriginalBinding {
  documentVersionId: string;
  parseRunId: string;
  parseRevision: number;
  sourceArtifactId: string;
  sourceSha256: string;
  sourceByteLength: number;
}

export interface DocumentOriginalCoverage {
  knownPageCount: number | null;
  /** Zero-based physical PDF pages. A read text layer does not imply understood figures. */
  readPageIndexes: number[];
  unresolvedRanges: Array<{
    pageIndexes: number[];
    unitIds: string[];
